<script setup lang="ts">
const auth = useAuth(), api = useApi()
interface Token { id: string; name: string; scopes: string[]; created_at: string; expires_at: string; last_used_at: string | null }
interface Session { id: string; created_at: string; last_seen_at: string; expires_at: string }
interface Mfa { enabled: boolean; pending: boolean; recovery_codes_left: number }
const scopes = ['profile:read', 'sessions:read', 'tokens:read']
const tokens = ref<Token[]>([]), sessions = ref<Session[]>([]), mfa = ref<Mfa | null>(null)
const tokenName = ref(''), selectedScopes = ref<string[]>(['profile:read']), tokenExpires = ref(2592000), newToken = ref('')
const currentPassword = ref(''), newPassword = ref(''), mfaPassword = ref(''), mfaCode = ref('')
const enrollment = ref<{secret:string;otpauth_url:string}|null>(null), recovery = ref<string[]>([])
const busy = ref(false), error = ref(''), success = ref('')
async function load() { busy.value = true; error.value = ''; try {
  const results = await Promise.all([api.get<{data:Token[]}>('/auth/tokens'), api.get<{data:Session[]}>('/auth/sessions'), api.get<Mfa>('/auth/mfa')])
  tokens.value = results[0].data; sessions.value = results[1].data; mfa.value = results[2]
} catch (e) { error.value = apiError(e).message } finally { busy.value = false } }
async function action(job: () => Promise<void>, reload = true) { busy.value = true; error.value = ''; success.value = ''; try { await job(); if (reload) await load() } catch (e) { error.value = apiError(e).message } finally { busy.value = false } }
async function issueToken() { await action(async () => { const data = await api.write<{token:string}>('POST','/auth/tokens',{name:tokenName.value,scopes:selectedScopes.value,expires_in:tokenExpires.value}); newToken.value = data.token; tokenName.value = ''; success.value = 'Токен создан. Сохраните его сейчас — повторно он не отображается.' }) }
async function revokeToken(id:string) { if (!confirm('Отозвать токен?')) return; await action(async()=>{ await api.write('DELETE',`/auth/tokens/${id}`); success.value = 'Токен отозван.' }) }
async function revokeSession(id:string) { if (!confirm('Завершить сессию?')) return; await action(async()=>{ await api.write('DELETE',`/auth/sessions/${id}`); success.value = 'Сессия отозвана.'; if (!(await auth.refresh())) await navigateTo('/login',{replace:true}) }) }
async function changePassword() { if (!confirm('Сменить пароль и завершить все сессии и токены?')) return; await action(async()=>{ await api.write('POST','/auth/password',{current_password:currentPassword.value,new_password:newPassword.value}); currentPassword.value='';newPassword.value=''; await auth.refresh(); await navigateTo('/login',{replace:true}) },false) }
async function enrollMfa() { await action(async()=>{ enrollment.value = await api.write('POST','/auth/mfa/enroll',{password:mfaPassword.value}); mfaPassword.value = ''; success.value='Добавьте секрет в приложение TOTP и подтвердите код.' },false) }
async function confirmMfa() { await action(async()=>{ const data = await api.write<{recovery_codes:string[]}>('POST','/auth/mfa/confirm',{code:mfaCode.value}); recovery.value=data.recovery_codes; enrollment.value=null; mfaCode.value=''; success.value='2FA включена. Сохраните резервные коды немедленно.' }) }
async function disableMfa() { if (!confirm('Отключить двухфакторную аутентификацию и завершить все сессии?')) return; await action(async()=>{ await api.write('POST','/auth/mfa/disable',{password:mfaPassword.value,code:mfaCode.value}); mfaPassword.value=''; mfaCode.value=''; await auth.refresh(); await navigateTo('/login',{replace:true}) },false) }
onMounted(()=>{ void load() })
</script>
<template><div><h1>Профиль и безопасность</h1><p class="page-subtitle">Сессии, токены и двухфакторная защита текущего пользователя: {{ auth.user?.email }}</p><UiAlert :message="error" /><UiAlert :message="success" tone="success" />
  <section class="panel"><h2>Сменить пароль</h2><p class="muted small">После смены все сессии и API-токены будут отозваны.</p><form @submit.prevent="changePassword"><div class="form-row"><div class="field"><label for="oldpass">Текущий пароль</label><input id="oldpass" v-model="currentPassword" type="password" autocomplete="current-password" required /></div><div class="field"><label for="newpass">Новый пароль (минимум 14 символов)</label><input id="newpass" v-model="newPassword" type="password" autocomplete="new-password" minlength="14" required /></div></div><button class="btn" type="submit" :disabled="busy">Сменить пароль</button></form></section>
  <section class="panel"><h2>Двухфакторная аутентификация</h2><p v-if="mfa" class="muted">{{ mfa.enabled ? `Включена, осталось резервных кодов: ${mfa.recovery_codes_left}` : mfa.pending ? 'Ожидается подтверждение' : 'Отключена' }}</p><form v-if="!mfa?.enabled && !enrollment" @submit.prevent="enrollMfa"><div class="field"><label for="mfa-password">Текущий пароль</label><input id="mfa-password" v-model="mfaPassword" type="password" required autocomplete="current-password" /></div><button class="btn" :disabled="busy">Начать подключение 2FA</button></form>
  <div v-if="enrollment" class="alert info"><p>Добавьте секрет вручную в приложение TOTP. Не передавайте его другим лицам.</p><pre class="mono">{{ enrollment.secret }}</pre></div><form v-if="enrollment" @submit.prevent="confirmMfa"><div class="field"><label for="confirm-mfa">Код TOTP</label><input id="confirm-mfa" v-model="mfaCode" autocomplete="one-time-code" required /></div><button class="btn primary" :disabled="busy">Подтвердить 2FA</button></form>
  <div v-if="recovery.length" class="alert info"><strong>Резервные коды (показываются один раз)</strong><pre class="mono">{{ recovery.join('\n') }}</pre><button class="btn" @click="recovery=[]">Я сохранил коды — скрыть</button></div>
  <form v-if="mfa?.enabled" @submit.prevent="disableMfa"><div class="form-row"><div class="field"><label for="disable-password">Текущий пароль</label><input id="disable-password" v-model="mfaPassword" type="password" required /></div><div class="field"><label for="disable-code">Код 2FA или резервный код</label><input id="disable-code" v-model="mfaCode" required /></div></div><button class="btn danger" :disabled="busy">Отключить 2FA</button></form></section>
  <section class="panel"><h2>API-токены</h2><p class="muted small">Новый токен показывается единожды. Создание и отзыв доступны только через сессию с CSRF.</p><div v-if="newToken" class="alert info"><strong>Созданный токен (сохраните сейчас):</strong><pre class="mono">{{ newToken }}</pre><button class="btn" @click="newToken=''">Скрыть токен</button></div><form @submit.prevent="issueToken"><div class="form-row"><div class="field"><label for="token-name">Название</label><input id="token-name" v-model="tokenName" required maxlength="100" /></div><div class="field"><label for="token-exp">Срок действия</label><select id="token-exp" v-model.number="tokenExpires"><option :value="86400">1 день</option><option :value="604800">7 дней</option><option :value="2592000">30 дней</option></select></div></div><div class="inline-actions"><label v-for="scope in scopes" :key="scope"><input v-model="selectedScopes" type="checkbox" :value="scope" style="width:auto" /> {{ scope }}</label></div><p><button class="btn primary" :disabled="busy">Создать токен</button></p></form><div class="table-wrap"><table class="table"><thead><tr><th>Название</th><th>Разрешения</th><th>Создан</th><th>Действие</th></tr></thead><tbody><tr v-for="token in tokens" :key="token.id"><td>{{ token.name }}</td><td class="small mono">{{ token.scopes.join(', ') }}</td><td>{{ token.created_at }}</td><td><button class="btn danger" :disabled="busy" @click="revokeToken(token.id)">Отозвать</button></td></tr></tbody></table></div></section>
  <section class="panel"><div class="toolbar"><h2>Активные сессии</h2><button class="btn" :disabled="busy" @click="load">Обновить</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Сессия</th><th>Последняя активность</th><th>Истекает</th><th></th></tr></thead><tbody><tr v-for="session in sessions" :key="session.id"><td class="mono small">{{ session.id }}</td><td>{{ session.last_seen_at }}</td><td>{{ session.expires_at }}</td><td><button class="btn danger" :disabled="busy" @click="revokeSession(session.id)">Завершить</button></td></tr></tbody></table></div></section>
</div></template>
